import { useEffect, useState } from "react";

interface Schedule {
  id: string;
  name: string;
  sourcePath: string;
  destinationPath: string;
  scheduleExpression: string;
  isEnabled: boolean;
}

export function BackupConfigurationUi() {
  const [schedules, setSchedules] = useState<Schedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: "",
    sourcePath: "",
    destinationPath: "",
    scheduleExpression: "",
    isEnabled: true
  });

  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchSchedules();
  }, []);

  const fetchSchedules = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/backup-scheduler/status');
      if (!response.ok) throw new Error('Failed to fetch schedules');
      const data = await response.json();
      setSchedules(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as HTMLInputElement | HTMLTextAreaElement;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = editingId 
        ? await fetch(`/api/backup-scheduler/schedule/${editingId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
          })
        : await fetch('/api/backup-scheduler/schedule', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
          });

      if (!response.ok) throw new Error('Failed to save schedule');

      // Reset form and refetch data
      setFormData({
        name: "",
        sourcePath: "",
        destinationPath: "",
        scheduleExpression: "",
        isEnabled: true
      });
      setEditingId(null);
      fetchSchedules();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (schedule: Schedule) => {
    setFormData({
      name: schedule.name,
      sourcePath: schedule.sourcePath,
      destinationPath: schedule.destinationPath,
      scheduleExpression: schedule.scheduleExpression,
      isEnabled: schedule.isEnabled
    });
    setEditingId(schedule.id);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/backup-scheduler/schedule/${id}`, {
        method: 'DELETE'
      });
      if (!response.ok) throw new Error('Failed to delete schedule');
      fetchSchedules();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const containerStyle: React.CSSProperties = {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ddd',
    borderRadius: '8px',
    padding: '16px',
    marginBottom: '16px',
    backgroundColor: '#f9f9f9'
  };

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '8px',
    marginBottom: '12px',
    borderRadius: '4px',
    border: '1px solid #ccc'
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    padding: '8px 16px',
    borderRadius: '4px',
    cursor: 'pointer',
    marginRight: '8px'
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '8px'
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;

  if (error) return (
    <div style={containerStyle}>
      <h2>Error</h2>
      <p>{error}</p>
    </div>
  );

  return (
    <div style={containerStyle}>
      <h1>Backup Configuration</h1>

      <form onSubmit={handleSubmit} style={cardStyle}>
        <h2>{editingId ? 'Edit Schedule' : 'Create New Schedule'}</h2>

        <input
          type="text"
          name="name"
          placeholder="Schedule Name"
          value={formData.name}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="sourcePath"
          placeholder="Source Path"
          value={formData.sourcePath}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="destinationPath"
          placeholder="Destination Path"
          value={formData.destinationPath}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="scheduleExpression"
          placeholder="Cron Expression"
          value={formData.scheduleExpression}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <label>
          <input
            type="checkbox"
            name="isEnabled"
            checked={formData.isEnabled}
            onChange={handleInputChange}
          /> Enable Schedule
        </label>

        <button type="submit" style={buttonStyle}>Save Schedule</button>
      </form>

      <h2>Saved Schedules</h2>

      {schedules.length === 0 ? (
        <p>No schedules found.</p>
      ) : (
        <div>
          {schedules.map(schedule => (
            <div key={schedule.id} style={cardStyle}>
              <h3>{schedule.name}</h3>
              <p><strong>Source:</strong> {schedule.sourcePath}</p>
              <p><strong>Destination:</strong> {schedule.destinationPath}</p>
              <p><strong>Schedule:</strong> {schedule.scheduleExpression}</p>
              <p><strong>Status:</strong> {schedule.isEnabled ? 'Enabled' : 'Disabled'}</p>

              <div style={buttonGroupStyle}>
                <button onClick={() => handleEdit(schedule)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(schedule.id)} style={buttonStyle}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

export function CollaborativeDocumentEditor() {
  const [documentId, setDocumentId] = useState<string>("");
  const [changes, setChanges] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!documentId) return;

    const fetchChanges = async () => {
      setLoading(true);
      setError(null);

      try {
        const response = await fetch(`/api/encrypted-sync-server/changes/${documentId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch changes: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setChanges(data.changes || []);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchChanges();

    // Poll for updates every 5 seconds
    const intervalId = setInterval(fetchChanges, 5000);

    return () => clearInterval(intervalId);
  }, [documentId]);

  const handleSync = async () => {
    if (!documentId) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/encrypted-sync-server/sync`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ documentId }),
      });

      if (!response.ok) {
        throw new Error(`Failed to sync: ${response.status} ${response.statusText}`);
      }

      // Refresh changes after sync
      const syncResponse = await fetch(`/api/encrypted-sync-server/changes/${documentId}`);
      if (!syncResponse.ok) {
        throw new Error(`Failed to fetch changes after sync: ${syncResponse.status} ${syncResponse.statusText}`);
      }

      const data = await syncResponse.json();
      setChanges(data.changes || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
    }}>
      <h1>Collaborative Document Editor</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="documentId" style={{ display: 'block', marginBottom: '5px' }}>
          Document ID:
        </label>
        <input
          id="documentId"
          type="text"
          value={documentId}
          onChange={(e) => setDocumentId(e.target.value)}
          style={{
            width: '100%',
            padding: '8px',
            borderRadius: '4px',
            border: '1px solid #ccc',
          }}
          placeholder="Enter document ID"
        />
      </div>

      <button
        onClick={handleSync}
        disabled={!documentId || loading}
        style={{
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          padding: '10px 16px',
          borderRadius: '4px',
          cursor: documentId && !loading ? 'pointer' : 'default',
          fontSize: '16px',
        }}
      >
        {loading ? 'Syncing...' : 'Sync Changes'}
      </button>

      {error && (
        <div style={{
          marginTop: '20px',
          padding: '10px',
          backgroundColor: '#f8d7da',
          borderColor: '#f5c6cb',
          color: '#721c24',
          borderRadius: '4px',
          border: '1px solid transparent',
        }}>
          Error: {error}
        </div>
      )}

      <h2 style={{ marginTop: '30px' }}>Recent Changes</h2>

      {loading ? (
        <p>Loading...</p>
      ) : changes.length === 0 ? (
        <p>No changes found.</p>
      ) : (
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '10px',
        }}>
          {changes.map((change, index) => (
            <div key={index} style={{
              padding: '10px',
              border: '1px solid #ddd',
              borderRadius: '4px',
              backgroundColor: '#f9f9f9',
            }}>
              <strong>Change #{index + 1}</strong>: {change.description || 'No description'}
              <br />
              <small>Timestamp: {new Date(change.timestamp).toLocaleString()}</small>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
